/** 运行时观测：用真实触点坐标连续注入连线，随后走消除→塌落→补充。 */
function runRuntimeChainChecks(): string {
	const failures: string[] = [];
	let checks = 0;
	const expect = (condition: boolean, message: string): void => {
		checks++;
		if (!condition && failures.length < 12) {
			failures.push(message);
		}
	};

	const board = new Board();
	const view = new BoardView(board);
	view.root.addTo(Director.entry);

	let operations = 0;
	let resolved = 0;
	let rejected = 0;
	let fullFails = 0;
	let limitFails = 0;
	let reserveFails = 0;

	for (let i = 0; i < 40; i++) {
		const chain = findPlayableChain(board, Config.MinChainLength, 3 + Math.floor(Math.random() * 4));
		if (chain.length === 0) {
			continue;
		}
		view.press(cellCenterPointFromFlat(chain[0]));
		for (let k = 1; k < chain.length; k++) {
			view.move(cellCenterPointFromFlat(chain[k]));
		}
		view.release(cellCenterPointFromFlat(chain[chain.length - 1]));
		operations++;
		const result = view.takePendingResult();
		if (result === undefined) {
			rejected++;
			continue;
		}
		resolved++;
		board.applyChain(result.cells);
		view.refreshFromBoard();
		if (!board.isFull()) {
			fullFails++;
		}
		if (!board.satisfiesGroupLimit(Config.GroupSizeRelaxLimit)) {
			limitFails++;
		}
		if (!board.hasReserveRegion(Config.ReserveGroupMin)) {
			reserveFails++;
		}
	}

	expect(operations >= 35, '运行时注入操作次数应 ≥ 35，实际 ' + operations);
	expect(resolved >= 35, '经真实触点链路解析的连线应 ≥ 35，实际 ' + resolved);
	expect(resolved + rejected === operations, '解析与被拒次数之和应等于操作次数');
	expect(fullFails === 0, '连续消除后出现非满格：' + fullFails + ' 次');
	expect(limitFails === 0, '连续消除后连通块超上限：' + limitFails + ' 次');
	expect(reserveFails === 0, '连续消除后缺少可预留区域：' + reserveFails + ' 次');
	expect(board.clearedTotal > 0, '消除统计应大于 0');
	expect(board.chainsTotal === resolved, '连线计数应与解析次数一致：' + board.chainsTotal + ' vs ' + resolved);

	const head = failures.length === 0 ? 'passed' : 'failed';
	const lines: string[] = [head];
	lines.push('运行时操作 ' + operations + ' 次，解析连线 ' + resolved + ' 次，低于下限被拒 ' + rejected + ' 次，检查 ' + checks + ' 项');
	const sizes: string[] = [];
	for (const size of board.maxGroupSizes()) {
		sizes.push('' + size);
	}
	lines.push('各类型最大连通块 ' + sizes.join(',') + '；满格=' + board.isFull() + ' 空格=' + board.emptyCount() + ' 已消除=' + board.clearedTotal + ' 连线次数=' + board.chainsTotal);
	for (const failure of failures) {
		lines.push(' - ' + failure);
	}
	return lines.join('\n');
}

/** 诊断信息：不参与 pass/fail 判定，仅用于定位生成/补充行为。 */
function runDiagnostics(): string {
	const lines: string[] = [];
	lines.push('Config.MaxGroupSize=' + Config.MaxGroupSize + ' MinChainLength=' + Config.MinChainLength + ' CellColorRetries=' + Config.CellColorRetries + ' 方块类型数=' + BlockDefs.count());
