	satisfiesGroupLimit(maxGroup: number): boolean {
		for (const size of this.maxGroupSizes()) {
			if (size > maxGroup) {
				return false;
			}
		}
		return true;
	}

	/** C2：每种颜色都存在长度 ≥ minSize 的连通区域（可预留的储备区域）。 */
	hasReserveRegion(minSize: number): boolean {
		for (const size of this.maxGroupSizes()) {
			if (size < minSize) {
				return false;
			}
		}
		return true;
	}

	/** 生成满足约束的满格棋盘；带重试上限与逐级放宽，绝不死循环。 */
	fill(): void {
		let maxGroup = Config.MaxGroupSize;
		for (let attempt = 0; attempt < Config.BoardRefillRetries; attempt++) {
			this.randomFill(maxGroup);
			if (this.hasPlayableRegion(Config.MinChainLength) && this.hasReserveRegion(Config.ReserveGroupMin)) {
