	for (let i = 0; i < BlockDefs.count(); i++) {
		const def = BlockDefs.at(i);
		expect(def.rules.length > 0, '方块 ' + def.id + ' 缺少效果规则');
		expect(resolveEffects(def.rules, Config.MinChainLength - 1).length === 0, '方块 ' + def.id + ' 在链长低于下限时不应产出效果');
