			const specs = resolveEffects(def.rules, n);
			expect(specs.length > 0, '方块 ' + def.id + ' 链长 ' + n + ' 未产出效果列表');
			for (const spec of specs) {
				expect(spec.value >= 1, '方块 ' + def.id + ' 链长 ' + n + ' 的效果数值应 ≥ 1，实际 ' + spec.value);
