		const board = new Board();
		if (board.isFull()) {
			fullCount++;
		}
		let maxSize = 0;
		for (const size of board.maxGroupSizes()) {
			if (size > maxSize) {
				maxSize = size;
			}
		}
		if (maxSize <= Config.MaxGroupSize) {
			strictCount++;
		}
		if (maxSize <= Config.GroupSizeRelaxLimit) {
			boundedCount++;
		}
		if (board.hasReserveRegion(Config.ReserveGroupMin)) {
