				let ok = true;
				for (let step = 1; step < length; step++) {
					const c = col + (dir === 0 ? step : 0);
					const r = row + (dir === 1 ? step : 0);
					if (!this.inside(c, r)) { ok = false; break; }
					const next = this.flatIndex(c, r);
					if (!inSlots[next]) { ok = false; break; }
					run.push(next);
				}
				if (ok) return run;
			}
