	private handleChain(result: ChainResult): void {
		if (this.defeated) {
			return;
		}
		this.combat.applySpecs(result.specs);
		this.board.applyChain(result.cells);
		this.view.refreshFromBoard();
		this.hud.showNotice(formatEffects(result.specs));
		const resetNotice = this.combat.ensureBoardPlayable();
		if (resetNotice !== undefined) {
			this.hud.showNotice(resetNotice);
			this.view.refreshFromBoard();
		}
		this.turnsUntilEnemy--;
		if (this.combat.enemy.hp <= 0) {
			this.handleWaveCleared();
		} else if (this.turnsUntilEnemy <= 0) {
			this.enemyAct();
		}
		if (this.combat.player.hp <= 0) {
			this.defeat();
			return;
		}
		this.refreshHud();
	}

	private handleWaveCleared(): void {
		if (this.combat.advanceWave()) {
			this.combat.nextStage();
			this.hud.showNotice('本关通关，进入第 ' + this.combat.stageNumber + ' 关');
		} else {
			this.hud.showNotice('第 ' + this.combat.waveNumber + ' 波出现');
		}
		this.turnsUntilEnemy = this.combat.enemyInterval;
	}

	private enemyAct(): void {
		const damage = this.combat.enemyAct();
		this.hud.showNotice('敌方出手，受到 ' + damage + ' 点伤害');
		this.turnsUntilEnemy = this.combat.enemyInterval;
	}

	private defeat(): void {
		this.defeated = true;
		this.hud.showDefeat('玩家生命归零：第 ' + this.combat.stageNumber + ' 关第 ' + this.combat.waveNumber + ' 波');
	}

	private restart(): void { ... reset board/combat/state and hide panel ... }

	private refreshHud(): void {
		this.hud.setStageInfo('第 ' + this.combat.stageNumber + ' 关 · 波次 ' + this.combat.waveNumber + '/' + this.combat.waveCount);
		this.hud.setEnemyInfo(this.combat.currentWaveName(), this.combat.enemy.hp, this.combat.enemy.maxHp);
		this.hud.updatePlayer(this.combat.player.hp, this.combat.player.maxHp, this.combat.player.mana, this.combat.player.maxMana);
		this.hud.setTimer('敌方行动倒计时 ' + this.turnsUntilEnemy + ' 回合');
		this.hud.syncSkills(Skills.List, this.combat.player.mana);
