// 入口：屏幕自适应 + 启动游戏主控制器（逐帧逻辑集中在 game/Game.ts 的单一 schedule 循环内）。

import { Director, Node, TypeName, Vec2, View, tolua } from 'Dora';
import { Config } from 'game/Config';
import { Game } from 'game/Game';

// 场景根：内容全部挂在其下，便于在拿不到 2D 摄像机时直接缩放整个场景。
const scene = Node();
scene.addTo(Director.entry);

const updateViewSize = (): void => {
	const widthScale = View.size.width / Config.DesignSceneWidth;
	const heightScale = View.size.height / Config.DesignSceneHeight;
	const scale = widthScale < heightScale ? widthScale : heightScale;
	const camera = tolua.cast(Director.currentCamera, TypeName.Camera2D);
	if (camera === undefined) {
		// 没有可用的 2D 摄像机时退化为直接缩放场景根节点，避免设计坐标被当成像素使用
		scene.scale = Vec2(scale, scale);
		return;
	}
	camera.zoom = scale;
	scene.scale = Vec2(1, 1);
};

updateViewSize();
Director.entry.onAppChange((settingName) => {
	if (settingName === 'Size') {
		updateViewSize();
	}
});

const game = new Game(scene);
game.start();
