function runGameLoopChecks(): string {
	const failures: string[] = [];
	let checks = 0;
	const expect = (condition: boolean, message: string): void => {
		checks++;
		if (!condition && failures.length < 12) {
			failures.push(message);
		}
	};

	const scene = Node();
	scene.addTo(Director.entry);
