			this.defeat();
			return;
		}
		this.refreshHud();
	}

	private handleWaveCleared(): void {
		if (this.combat.advanceWave()) {
			this.combat.nextStage();
			this.hud.showNotice('本关通关，进入第 ' + this.combat.stageNumber + ' 关（生命已回复）');
