/** 统一创建文本标签（`Label` 可能返回 undefined，因此集中判空与设置锚点）。 */
export function makeLabel(text: string, fontSize: number): Label.Type | undefined {
	const label = Label('sarasa-mono-sc-regular', fontSize);
