// 入口：屏幕自适应 + 启动游戏主控制器（逐帧逻辑集中在 game/Game.ts 的单一 schedule 循环内）。

import { Director, Node, TypeName, View, tolua } from 'Dora';
import { Config } from 'game/Config';
import { Game } from 'game/Game';

// 场景根：内容全部挂在其下，便于在拿不到 2D 摄像机时直接缩放整个场景。
const scene = Node();
scene.addTo(Director.entry);

const updateViewSize = (): void => {
	let width = View.size.width;
	let height = View.size.height;
	if (width < 1) {
		width = Config.DesignSceneWidth;
	}
	if (height < 1) {
		height = Config.DesignSceneHeight;
	}
	const widthScale = width / Config.DesignSceneWidth;
	const heightScale = height / Config.DesignSceneHeight;
	let scale = widthScale < heightScale ? widthScale : heightScale;
	if (scale < 0.05) {
		// 防止窗口未就绪（尺寸为 0）时把 zoom 算成 0，导致画面全黑
		scale = 0.05;
	}
	const camera = tolua.cast(Director.currentCamera, TypeName.Camera2D);
	if (camera === undefined) {
		// 没有可用的 2D 摄像机时退化为直接缩放场景根节点，避免设计坐标被当成像素使用
		scene.scaleX = scale;
		scene.scaleY = scale;
		return;
	}
	camera.zoom = scale;
	scene.scaleX = 1;
	scene.scaleY = 1;
};

updateViewSize();
Director.entry.onAppChange((settingName) => {
	if (settingName === 'Size') {
		updateViewSize();
	}
});

// 窗口可能在入口初始化后才就绪，因此在场景根的独立 schedule 槽里再校正一次（只执行一次）
scene.schedule(() => {
	updateViewSize();
	return true;
});

const game = new Game(scene);
game.start();


