		this.root.onTapMoved((touch) => this.handleTapMoved(touch.location));
		this.root.onTapEnded((touch) => this.handleTapEnded(touch.location));
	}

	setSelected(on: boolean): void {
		if (this.selected === on) {
			return;
		}
		this.selected = on;
		this.redraw();
