		const widget = this.floats[this.floatCursor];
		this.floatCursor = (this.floatCursor + 1) % this.floats.length;
		widget.show(text, 0xffe58a, 0, Config.NoticeY);
	}

	showDefeat(text: string): void {
		if (this.panelText !== undefined) {
			this.panelText.text = text;
		}
