```
new:
```
	setPosition(x: number, y: number): void {
		this.baseX = x;
		this.baseY = y;
		this.root.position = Vec2(x, y);
	}

	/** 受击抖动：在持续时间内围绕基准位置晃动（子类 update 里调用 advanceJuice 推进）。 */
	shake(duration: number, amplitude: number): void {
		this.shakeTimer = duration;
		this.shakeDuration = duration;
		this.shakeAmplitude = amplitude;
	}

	/** 推进抖动动画；子类若重写 update 需先调用它。 */
	protected advanceJuice(dt: number): void {
		if (this.shakeTimer <= 0) {
			return;
		}
		this.shakeTimer -= dt;
		if (this.shakeTimer <= 0) {
			this.shakeTimer = 0;
			this.root.position = Vec2(this.baseX, this.baseY);
			return;
		}
		const t = this.shakeTimer / this.shakeDuration;
		const offset = this.shakeAmplitude * t;
		const phase = this.shakeTimer * 46;
		this.root.position = Vec2(this.baseX + Math.sin(phase) * offset, this.baseY + Math.cos(phase * 1.7) * offset * 0.4);
	}
```

