		this.shakeDuration = duration > 0 ? duration : 0.24;
		this.shakeAmplitude = amplitude;
		this.shakeTimer = this.shakeDuration;
	}

	/** 推进抖动动画（由子类 update 调用，控件不自行注册 schedule）。 */
	protected advanceShake(dt: number): void {
