	constructor(width: number, height: number, fillHex: number) {
		super(width, height);
		this.fillHex = fillHex;
		const label = makeLabel('', Math.max(14, Math.floor(height * 0.66)));
		if (label !== undefined) {
			label.position = Vec2(width / 2, height / 2);
