`showNotice(text, lane = NoticeLane.System, hex = 0xffe58a)`:
```ts
	showNotice(text: string, lane: number = NoticeLane.System, hex: number = 0xffe58a): void {
		if (this.floatLanes.length === 0) return;
		const index = lane < 0 || lane >= this.floatLanes.length ? NoticeLane.System : lane;
		const widget = this.floatLanes[index];
		if (!widget.active) { this.playNotice(index, text, hex); return; }
		const queue = this.floatQueue[index];
		const hexes = this.floatQueueHex[index];
		if (queue.length >= 3) { queue.shift(); hexes.shift(); }
		queue.push(text);
		hexes.push(hex);
	}
	private playNotice(lane: number, text: string, hex: number): void {
		const widget = this.floatLanes[lane];
		if (lane === NoticeLane.Enemy) { widget.show(text, hex, Config.NoticeEnemyX, Config.NoticeEnemyY); }
		else if (lane === NoticeLane.Player) { widget.show(text, hex, Config.NoticePlayerX, Config.NoticePlayerY); }
		else { widget.show(text, hex, Config.NoticeSystemX, Config.NoticeSystemY); }
	}
```
