					nextCol = tailCol + (dc > 0 ? 1 : -1);
					nextRow = tailRow;
				} else {
					nextCol = tailCol;
					nextRow = tailRow + (dr > 0 ? 1 : -1);
				}
			}
			const before = chain.length;
			this.appendCell(this.board.flatIndex(nextCol, nextRow));
			if (this.chain.length === before) {
				return;
			}
		}
	}

