		if (ratio > 1) {
			ratio = 1;
		}
		this.targetRatio = ratio;
		if (!this.initialized) {
			// 首次赋值直接对齐，避免启动时出现无意义的滑动
			this.initialized = true;
			this.shownRatio = ratio;
