		this.hud.onRestart = () => this.restart();
		this.hud.onToggleMode = () => this.toggleMode();
		this.hud.onCycleDifficulty = () => this.cycleDifficulty();
		this.hud.onToggleHint = () => this.toggleHint();
		this.turnsUntilEnemy = this.combat.enemyInterval;
