export class Board {
	readonly columns = Config.Columns;
	readonly rows = Config.Rows;
	/** 每格的方块类型在注册表中的下标；-1 表示空格。始终满长度，不留 Lua 空洞。 */
	private cells: number[] = [];
	/** 累计消除块数（消除统计）。 */
	private clearedCount = 0;
	/** 累计有效连线次数（消除统计）。 */
	private chainCount = 0;
	/** 棋盘无解时被迫强行修复的次数。 */
	private forcedRepairCount = 0;
