		for (let i = 0; i < BlockDefs.count(); i++) {
			result.push(0);
		}
		const visited = this.makeVisited();
		for (let row = 0; row < this.rows; row++) {
			for (let col = 0; col < this.columns; col++) {
				const flat = this.flatIndex(col, row);
				if (visited[flat]) {
					continue;
				}
				const target = this.cells[flat];
				if (target < 0) {
