	/** 取棋盘左下方第一行的前 MinChainLength 个格子（用于强行构造可连线区域）。 */
	private lineCells(): number[] {
		const cells: number[] = [];
		for (let i = 0; i < Config.MinChainLength && i < this.columns; i++) {
			cells.push(this.flatIndex(i, 0));
