	private trackTo(location: Vec2.Type): void {
		const dx = location.x - this.lastX;
		const dy = location.y - this.lastY;
		const dist = Math.sqrt(dx * dx + dy * dy);
		const step = Config.CellSize * 0.5;
		if (dist > step) {
			let samples = Math.floor(dist / step);
			if (samples > 16) {
