			const r = Math.floor(current / this.columns);
			this.pushNeighbor(stack, visited, c - 1, r, target);
			this.pushNeighbor(stack, visited, c + 1, r, target);
			this.pushNeighbor(stack, visited, c, r - 1, target);
			this.pushNeighbor(stack, visited, c, r + 1, target);
