	/** 该格是否为封锁格（不可消除、不可放置方块）。 */
	isLocked(col: number, row: number): boolean {
		const index = this.cellIndex(col, row);
		return index >= 0 && !BlockDefs.isPlaceable(index);
	}

	/** 当前在场封锁格数量（HUD 与自检观测用）。 */
	get lockedCount(): number {
		return this.lockedCells().length;
	}

	/** 当前在场封锁格的 flat 下标列表。 */
	lockedCells(): number[] {
		const result: number[] = [];
		for (let i = 0; i < this.cells.length; i++) {
			const index = this.cells[i];
			if (index >= 0 && !BlockDefs.isPlaceable(index)) {
				result.push(i);
			}
		}
		return result;
	}

	/** 把指定格变成封锁格（确定性接口，供效果执行器与自检使用）。 */
	lockCell(col: number, row: number): boolean {
		if (!this.inside(col, row)) {
			return false;
		}
		const index = this.cellIndex(col, row);
		if (index >= 0 && !BlockDefs.isPlaceable(index)) {
			return false;
		}
		this.setCell(col, row, BlockDefs.lockedIndex());
		return true;
	}

	/**
	 * `BoardOps` 实现：随机封锁 count 格（封锁后若棋盘不再可执行则还原该格）。
	 * 返回实际封锁的格数。
	 */
	blockCells(count: number): number {
		let placed = 0;
		const limit = count > 0 ? count : 0;
		for (let attempt = 0; attempt < limit * 8 && placed < limit; attempt++) {
			const col = Math.floor(Math.random() * this.columns);
			const row = Math.floor(Math.random() * this.rows);
			const previous = this.cellIndex(col, row);
			if (previous >= 0 && !BlockDefs.isPlaceable(previous)) {
				continue;
			}
			if (!this.lockCell(col, row)) {
				continue;
			}
			if (!this.isPlayable()) {
				this.setCell(col, row, previous);
				continue;
			}
			placed++;
		}
		return placed;
	}

	/** 解除全部封锁格：先清空再由重力与补充恢复满格（波次/关卡切换时调用）。 */
	clearLocks(): number {
		const cells = this.lockedCells();
		if (cells.length === 0) {
			return 0;
		}
		for (const flat of cells) {
			this.cells[flat] = -1;
		}
		this.collapse();
		this.refillRestore();
		return cells.length;
	}
