		collectOption(board, options, used, col + 1, row, type);
		collectOption(board, options, used, col, row - 1, type);
		collectOption(board, options, used, col, row + 1, type);
		if (options.length === 0) {
			break;
		}
		const pick = options[Math.floor(Math.random() * options.length)];
		used[pick] = true;
		chain.push(pick);
	}
	return chain;
}

