	 * 颜色取“使全盘最大连通块最小”的那个，避免接上已有大色块。
	 */
	private applyPlayableGroup(cells: number[]): boolean {
		const length = Config.MinChainLength;
		if (cells.length < length) {
			return false;
		}
		// 只用可放置方块的颜色（封锁格不是备选颜色）
		const total = BlockDefs.placeableCount();
