		const saved = this.settings.save();
		this.combat.setDifficultyScale(this.settings.difficultyScale());
		this.combat.loadWave();
		this.hud.showNotice('难度：' + this.settings.difficultyName() + (saved ? '' : '（设置未保存）'));
		this.refreshHud();
	}

