blockCells(count: number): number {
    const locked = BlockDefs.lockedIndex();
    if (locked < 0 || count <= 0) {
        return 0;
    }
    const candidates = this.lockCandidates();
    let blocked = 0;
    for (const flat of candidates) {
        if (blocked >= count) {
            break;
