        const original = this.cells[flat];
        this.cells[flat] = locked;
        if (this.hasPlayableRegion(Config.MinChainLength)) {
            blocked++;
            continue;
        }
        this.cells[flat] = original; // 回滚：封锁不能把棋盘变成无解
    }
    return blocked;
}
