Getting complicated. Use a straightforward approach: compute group sizes for all cells first into an array `size[]` plus a group id per cell; then sort cells by size descending using a simple insertion into a new array (no splice):

```ts
/** 封锁候选格：按所在连通块规模从大到小排序（优先封锁玩家当下最长的连线段）。 */
private lockCandidates(): number[] {
	const sizeByFlat: number[] = [];
	for (let i = 0; i < this.cells.length; i++) {
		sizeByFlat.push(0);
	}
	const visited = this.makeVisited();
	for (let row = 0; row < this.rows; row++) {
		for (let col = 0; col < this.columns; col++) {
			const flat = this.flatIndex(col, row);
			if (visited[flat]) {
				continue;
			}
			const target = this.cells[flat];
			if (target < 0 || !BlockDefs.isPlaceable(target)) {
				visited[flat] = true;
				continue;
			}
			const group = this.collectGroup(col, row, visited, target);
			for (const member of group) {
				sizeByFlat[member] = group.length;
			}
		}
	}
	// 选择排序：规模大者在前，规模相同保持行优先顺序（确定性，便于自检）
	const order: number[] = [];
	const taken: boolean[] = [];
	for (let i = 0; i < this.cells.length; i++) {
		taken.push(false);
	}
	for (let round = 0; round < this.cells.length; round++) {
		let best = -1;
		let bestSize = 0;
		for (let flat = 0; flat < this.cells.length; flat++) {
			if (taken[flat] || sizeByFlat[flat] <= 0) {
				continue;
			}
			if (best < 0 || sizeByFlat[flat] > bestSize) {
				best = flat;
				bestSize = sizeByFlat[flat];
			}
		}
		if (best < 0) {
			break;
		}
		taken[best] = true;
		order.push(best);
	}
	return order;
}
```
