		}
		return result;
	}

	/** C1：任一颜色的最大连通块规模不得超过 maxGroup。 */
	satisfiesGroupLimit(maxGroup: number): boolean {
		for (const size of this.maxGroupSizes()) {
			if (size > maxGroup) {
				return false;
			}
		}
		return true;
	}

