		this.randomFill(Config.GroupSizeRelaxLimit);
		this.applyPlayableGroup(this.lineCells());
	}

	/** 累计消除块数。 */
	get clearedTotal(): number {
		return this.clearedCount;
	}

	/** 累计有效连线次数。 */
	get chainsTotal(): number {
		return this.chainCount;
	}

