	ensureBoardPlayable(): string | undefined {
		if (this.board.isPlayable()) {
			return undefined;
		}
		this.board.reset();
		this.resetCount++;
		this.player.hp -= Config.BoardResetPenalty;
		if (this.player.hp < 0) {
