function cellCenterPointFromFlat(flat: number): Vec2.Type {
	const col = flat % Config.Columns;
	const row = Math.floor(flat / Config.Columns);
	return Vec2((col + 0.5) * Config.CellSize, (row + 0.5) * Config.CellSize);
}

