// 排版与配色常量（M6）：HUD/棋盘在设计空间中的坐标、字号与颜色的唯一来源。
// 目的：让“排版统一”可审计——所有位置/尺寸集中此处，并由 game/Tests.ts 的
// 安全区检查断言「任何宽高比下都保证可见的 960×1080 设计盒」内不被裁切。

import { Config } from 'game/Config';

/** 设计空间安全区：任何宽高比下都保证可见的区域（半宽/半高，原点为屏幕中心）。 */
export class SafeBox {
	/** 半宽：Config.DesignSceneWidth / 2。 */
	static readonly HalfWidth = Config.DesignSceneWidth / 2;
	/** 半高：Config.DesignSceneHeight / 2。 */
	static readonly HalfHeight = Config.DesignSceneHeight / 2;
}

/** 一个矩形范围的审计条目（中心点 + 宽高，设计单位）。 */
export interface LayoutRect {
	name: string;
	x: number;
	y: number;
	width: number;
	height: number;
}

/**
 * 由窗口尺寸计算摄像机 zoom：宽高各自按基准缩放后取最小，
 * 保证至少 960×1080 设计单位可见。窗口未就绪（宽或高 < 1）时按基准尺寸处理。
 */
export function zoomFor(viewWidth: number, viewHeight: number): number {
	let width = viewWidth;
	let height = viewHeight;
	if (width < 1) width = Config.DesignSceneWidth;
	if (height < 1) height = Config.DesignSceneHeight;
	const widthScale = width / Config.DesignSceneWidth;
	const heightScale = height / Config.DesignSceneHeight;
	const scale = widthScale < heightScale ? widthScale : heightScale;
	if (scale < 0.05) {
		// 防止窗口未就绪（尺寸为 0）时把 zoom 算成 0，导致画面全黑
		return 0.05;
	}
	return scale;
}

/** 当前窗口在给定 zoom 下实际可见的设计空间半宽/半高。 */
export function visibleHalfExtent(viewWidth, viewHeight): { halfWidth: number; halfHeight: number } {
	const zoom = zoomFor(viewWidth, viewHeight);
	const width = viewWidth < 1 ? Config.DesignSceneWidth : viewWidth;
	const height = viewHeight < 1 ? Config.DesignSceneHeight : viewHeight;
	return { halfWidth: width / zoom * 0.5, halfHeight: height / zoom * 0.5 };
}

/** 矩形是否完全落在安全区内。 */
export function insideSafeBox(rect: LayoutRect): boolean {
	return Math.abs(rect.x) + rect.width * 0.5 <= SafeBox.HalfWidth + 0.001
		&& Math.abs(rect.y) + rect.height * 0.5 <= SafeBox.HalfHeight + 0.001;
}
