}

/** 单波敌人的纯数据定义。 */
export interface WaveDef {
	name: string;
	isElite: boolean;
	hp: number;
	attack: number;
	heavyAttack: number;
	armor: number;
	actionTurns: number;
	actionSeconds: number;
}

/**
